#include "stdafx.h"#include "CommProc.h"#include <Common.h>#include "Sound.h"#pragma comment(lib, "Winmm.lib")//for PlaySoundCSound sound;void SoundPlay(const char* pszSound, bool bData)  {  sound.Play(pszSound, bData);  }void SoundPlay()  {  sound.Play(NULL);  }void SoundStop()  {  sound.Stop();  }// System Sounds Filesconst LPCTSTR CSound::m_szSounds[] =  {  "WAV\\Сирена.wav"  };//////////////////////////////////////////////////////////////////////// Construction/Destruction//////////////////////////////////////////////////////////////////////CSound::CSound() : m_nCount(0)  {  }//###########################################################CSound::~CSound()  {  //Stop();  }//###########################################################void CSound::Stop()  {  if ( m_nCount > 0 )    {    PlaySound( NULL, 0, 0);    m_nCount = 0;    }  }//###########################################################void CSound::Play(const char* pszSound, bool bData)  {  if ( m_nCount != 0 ) return;  DWORD dwSndParams = SND_FILENAME|SND_ASYNC|SND_NOWAIT|SND_NODEFAULT;  CharMP szFile;  if ( pszSound == NULL )    {    sprintf_s( szFile, SizeMP, "%s%s", ::GetBasePath(), m_szSounds[0] );    }  else    {    CModelInfo& model = ::ModelInfo();    if(!bData)    sprintf_s( szFile, SizeMP, "%sSound/%s", model.dirProject, pszSound );    else      sprintf_s( szFile, SizeMP, "%sDATA\\%s", model.dirProject, pszSound );    }  if ( ::PlaySound( szFile, NULL, SND_ASYNC|SND_FILENAME|SND_LOOP|SND_NOWAIT ) )    m_nCount++;  }